import os
from typing import Any, Dict, List, Optional

import requests


AZURE_FORM_RECOGNIZER_ENDPOINT = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
AZURE_FORM_RECOGNIZER_KEY = os.getenv("AZURE_FORM_RECOGNIZER_KEY")
AZURE_FORM_RECOGNIZER_API_VERSION = "2023-07-31"
AZURE_FORM_RECOGNIZER_MODEL_ID = "prebuilt-layout"


def _check_config() -> None:
    if not AZURE_FORM_RECOGNIZER_ENDPOINT:
        raise ValueError("Missing AZURE_FORM_RECOGNIZER_ENDPOINT")
    if not AZURE_FORM_RECOGNIZER_KEY:
        raise ValueError("Missing AZURE_FORM_RECOGNIZER_KEY")


def _headers(content_type: str) -> Dict[str, str]:
    return {
        "Ocp-Apim-Subscription-Key": AZURE_FORM_RECOGNIZER_KEY,
        "Content-Type": content_type,
    }


def _post_analyze(file_path: str) -> str:
    url = (
        f"{AZURE_FORM_RECOGNIZER_ENDPOINT.rstrip('/')}"
        f"/formrecognizer/documentModels/{AZURE_FORM_RECOGNIZER_MODEL_ID}:analyze"
        f"?api-version={AZURE_FORM_RECOGNIZER_API_VERSION}"
    )
    with open(file_path, "rb") as f:
        resp = requests.post(
            url,
            headers=_headers("application/octet-stream"),
            data=f,
            timeout=120,
        )
    resp.raise_for_status()
    operation_url = resp.headers.get("operation-location")
    if not operation_url:
        raise RuntimeError("Missing operation-location header from Azure response")
    return operation_url


def _poll_result(operation_url: str, timeout_s: int = 120, poll_interval_s: float = 1.0) -> Dict[str, Any]:
    import time

    deadline = time.time() + timeout_s
    while time.time() < deadline:
        resp = requests.get(
            operation_url,
            headers={"Ocp-Apim-Subscription-Key": AZURE_FORM_RECOGNIZER_KEY},
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json()
        status = payload.get("status")
        if status in ("succeeded", "failed", "canceled"):
            if status != "succeeded":
                raise RuntimeError(f"Azure analyze failed with status: {status}")
            return payload
        time.sleep(poll_interval_s)
    raise TimeoutError("Timed out waiting for Azure Document Intelligence analysis")


def _normalize_tables(result_payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    analyze_result = result_payload.get("analyzeResult", {})
    tables = analyze_result.get("tables", []) or []

    normalized: List[Dict[str, Any]] = []
    for table in tables:
        cells = []
        for cell in table.get("cells", []) or []:
            cells.append(
                {
                    "rowIndex": cell.get("rowIndex"),
                    "columnIndex": cell.get("columnIndex"),
                    "rowSpan": cell.get("rowSpan", 1),
                    "columnSpan": cell.get("columnSpan", 1),
                    "kind": cell.get("kind"),
                    "content": cell.get("content", ""),
                    "boundingRegions": cell.get("boundingRegions", []),
                    "spans": cell.get("spans", []),
                }
            )

        rows: Dict[int, Dict[int, Dict[str, Any]]] = {}
        for cell in cells:
            r = cell["rowIndex"]
            c = cell["columnIndex"]
            rows.setdefault(r, {})[c] = cell

        ordered_rows: List[List[Dict[str, Any]]] = []
        if rows:
            max_row = max(rows.keys())
            for r in range(max_row + 1):
                row_cells = rows.get(r, {})
                if row_cells:
                    max_col = max(row_cells.keys())
                    ordered_rows.append([row_cells.get(c) for c in range(max_col + 1)])
                else:
                    ordered_rows.append([])

        normalized.append(
            {
                "rowCount": table.get("rowCount"),
                "columnCount": table.get("columnCount"),
                "cells": cells,
                "rows": ordered_rows,
                "boundingRegions": table.get("boundingRegions", []),
                "spans": table.get("spans", []),
            }
        )
    return normalized


def extract_table_cells_and_rows(document_path: str) -> List[Dict[str, Any]]:
    _check_config()
    operation_url = _post_analyze(document_path)
    result_payload = _poll_result(operation_url)
    return _normalize_tables(result_payload)
